<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';
const dashboard=ref(null),loading=ref(false),error=ref(''),category=ref('all'),search=ref(''),priority=ref('all'),chartStyle=ref('donut'),autoRefresh=ref(false);
const groups=[{id:'governance',label:'Assessment dan kebijakan'},{id:'risk',label:'Risiko dan audit'},{id:'assets',label:'Asset Management'},{id:'vendors',label:'TPRM'},{id:'people',label:'Personel'},{id:'knowledge',label:'Knowledge dan file'},{id:'system',label:'Administrasi'}];
const modules=computed(()=>dashboard.value?.modules||[]);
const visibleModules=computed(()=>modules.value.filter(m=>(category.value==='all'||m.group===category.value)&&[m.title,m.unit].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())&&(priority.value==='all'||priority.value==='deadlines'&&(m.overdue>0||m.upcoming>0)||priority.value==='overdue'&&m.overdue>0||priority.value==='upcoming'&&m.upcoming>0||priority.value==='references'&&m.reference||priority.value==='unavailable'&&m.state==='unavailable'||priority.value==='critical'&&m.issues?.critical>0||priority.value==='pending'&&m.issues?.pending>0||priority.value==='incomplete'&&m.issues?.incomplete>0||priority.value==='operational'&&m.issues?.operational>0)));
const totals=computed(()=>({modules:visibleModules.value.filter(m=>m.state==='ready').length,overdue:visibleModules.value.reduce((n,m)=>n+(m.overdue||0),0),upcoming:visibleModules.value.reduce((n,m)=>n+(m.upcoming||0),0),unavailable:visibleModules.value.filter(m=>m.state==='unavailable').length,critical:visibleModules.value.reduce((n,m)=>n+(m.issues?.critical||0),0),pending:visibleModules.value.reduce((n,m)=>n+(m.issues?.pending||0),0),incomplete:visibleModules.value.reduce((n,m)=>n+(m.issues?.incomplete||0),0),references:visibleModules.value.filter(m=>m.reference).length}));
const attention=computed(()=>visibleModules.value.filter(m=>m.state==='unavailable'||m.overdue>0||m.upcoming>0||Object.values(m.issues||{}).some(n=>n>0)).sort((a,b)=>Number(b.state==='unavailable')-Number(a.state==='unavailable')||(b.overdue||0)-(a.overdue||0)||(b.issues?.critical||0)-(a.issues?.critical||0)||(b.upcoming||0)-(a.upcoming||0)));
const attentionPage=ref(1),attentionPages=computed(()=>Math.max(1,Math.ceil(attention.value.length/8)));
const pagedAttention=computed(()=>attention.value.slice((attentionPage.value-1)*8,attentionPage.value*8));
watch([category,search,priority],()=>attentionPage.value=1);
watch(attentionPages,count=>attentionPage.value=Math.min(attentionPage.value,count));
const groupSummary=computed(()=>groups.map(g=>{const items=visibleModules.value.filter(m=>m.group===g.id);return {...g,total:items.length,ready:items.filter(m=>m.state==='ready').length,unavailable:items.filter(m=>m.state==='unavailable').length,attention:items.filter(m=>m.overdue>0||m.upcoming>0||Object.values(m.issues||{}).some(n=>n>0)).length};}).filter(g=>g.total));
const trend=computed(()=>{const base=visibleModules.value.find(m=>m.trend?.length)?.trend||[];return base.map(p=>({label:p.label,value:visibleModules.value.reduce((sum,m)=>sum+(m.trend?.find(t=>t.label===p.label)?.value||0),0)}));});
const updated=computed(()=>dashboard.value?.generatedAt?new Date(dashboard.value.generatedAt).toLocaleString(document.documentElement.lang==='en'?'en-GB':'id-ID',{timeZone:'Asia/Bangkok'}):'');
const maxTrend=computed(()=>Math.max(1,...trend.value.map(p=>p.value)));
const trendPoints=computed(()=>trend.value.map((p,i)=>({x:50+i*116,y:160-p.value/maxTrend.value*120,...p})));
const trendLine=computed(()=>trendPoints.value.map((p,i)=>`${i?'L':'M'}${p.x},${p.y}`).join(' '));
function chartColor(label,index){const lower=label.toLowerCase();if(/critical|very high|high|tinggi|expired|gagal/.test(lower))return '#e25964';if(/medium|pending|draft|progress|belum|planned/.test(lower))return '#eeb550';if(/low|active|approved|complete|closed|berhasil|achieved|terpakai/.test(lower))return '#32a98b';return ['#4b83da','#7e6dcc','#42b7bf','#e98b57','#a0b650','#7891ab'][index%6];}
function slices(module){const values=(module.distribution||[]).filter(p=>p.value>0);const series=values.length>6?[...values.slice(0,5),{label:'Lainnya',value:values.slice(5).reduce((n,p)=>n+p.value,0)}]:values;const total=series.reduce((n,p)=>n+p.value,0);let offset=0;return series.map((p,i)=>{const percent=total?p.value/total*100:0,result={...p,percent,offset,color:chartColor(p.label,i)};offset+=percent;return result;});}
function openModule(module){
 if(module.state!=='ready')return;
 const isoButton=module.id==='iso27001-soa'?document.querySelector('[data-view="iso27001"]'):null;
 const integratedSoa=isoButton&&!isoButton.hidden&&!isoButton.disabled;
 const button=integratedSoa?isoButton:module.view==='account'?document.getElementById('accountButton'):document.querySelector(`[data-view="${CSS.escape(module.view)}"]`);
 if(!button||button.disabled||button.hidden&&module.id!=='iso27001-soa')return;
 button.click();
 const accountTab={account:'users','audit-events':'audit',smtp:'smtp',storage:'storage'}[module.id];
 if(accountTab)setTimeout(()=>document.querySelector(`[data-account-tab="${accountTab}"]`)?.click(),0);
 const isoTab=module.id==='iso-objectives'?'objectives':integratedSoa?'soa':null;
 if(isoTab)setTimeout(()=>document.querySelector(`[data-iso-tab="${isoTab}"]`)?.click(),0);
}
function exportSummary(){const rows=visibleModules.value;const payload={generatedAt:dashboard.value.generatedAt,timezone:'Asia/Bangkok',filters:{category:category.value,search:search.value,priority:priority.value},totals:totals.value,modules:rows};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='it-governance-monitoring-'+new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok'}).format(new Date())+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let controller,refreshTimer,restoreTimer;
async function loadDashboard(){
 if(loading.value)return;loading.value=true;error.value='';controller=new AbortController();
 const timeout=setTimeout(()=>controller?.abort(),30000);
 try{const response=await fetch('/api/monitoring-dashboard',{cache:'no-store',signal:controller.signal});const body=await response.json();if(!response.ok){if([401,403].includes(response.status))dashboard.value=null;throw Error(body.error||'Dashboard tidak dapat dimuat.');}dashboard.value=body;}
 catch(e){error.value=e.name==='AbortError'?'Permintaan dashboard terlalu lama. Coba muat ulang.':e.message;}
 finally{clearTimeout(timeout);loading.value=false;controller=null;}
}
function showDashboard(){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active-view'));document.getElementById('monitoringDashboardView')?.classList.add('active-view');document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view==='monitoring-dashboard'));try{const state=JSON.parse(localStorage.getItem('nist-maturity-ui')||'{}');localStorage.setItem('nist-maturity-ui',JSON.stringify({...state,view:'monitoring-dashboard'}));}catch{}loadDashboard();}
function navigate(event){if(event.target.closest('[data-view]')?.dataset.view!=='monitoring-dashboard')return;event.preventDefault();event.stopImmediatePropagation();showDashboard();}
function restore(){try{if((JSON.parse(localStorage.getItem('nist-maturity-ui')||'{}').view||'monitoring-dashboard')==='monitoring-dashboard')showDashboard();}catch{}}
onMounted(()=>{document.addEventListener('click',navigate,true);window.addEventListener('vue:workspace-ready',restore);window.addEventListener('assessment-gaps-changed',loadDashboard);restoreTimer=setTimeout(restore,0);refreshTimer=setInterval(()=>{if(autoRefresh.value&&document.visibilityState==='visible'&&document.getElementById('monitoringDashboardView')?.classList.contains('active-view'))loadDashboard();},60000);});
onBeforeUnmount(()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('vue:workspace-ready',restore);window.removeEventListener('assessment-gaps-changed',loadDashboard);clearTimeout(restoreTimer);clearInterval(refreshTimer);controller?.abort();});
</script>

<template>
<section id="monitoringDashboardView" class="view monitoring-dashboard">
 <div class="page-heading"><div><p class="eyebrow">MONITORING DASHBOARD</p><h2>Monitoring Dashboard</h2><p class="lede">Ringkasan seluruh IT Governance: assessment, kepatuhan, risiko, audit, kebijakan, aset, vendor, personel, knowledge, evidence, dan administrasi.</p></div><div class="csf-actions"><button class="button button-quiet" :disabled="!dashboard||loading" @click="exportSummary">Export ringkasan JSON</button><button class="button button-accent" :disabled="loading" @click="loadDashboard">{{loading?'Memuat...':'Muat ulang'}}</button></div></div>
 <div class="monitor-hero"><div><span class="monitor-live-dot" aria-hidden="true"></span><strong>Ringkasan operasional</strong><p>Data aktual dari modul yang dapat Anda akses.</p><small v-if="updated"><span>Terakhir diperbarui:</span> <span data-no-translate>{{updated}} &middot; UTC+7</span></small></div><label class="monitor-auto"><input v-model="autoRefresh" type="checkbox"> Perbarui otomatis setiap 60 detik</label></div>
 <p v-if="error" class="monitor-error" role="alert">{{error}}</p><p v-if="loading&&!dashboard" class="insight-panel" role="status">Memuat ringkasan modul...</p>
 <template v-if="dashboard">
 <div class="toolbar monitor-filters"><label>Cari modul<input v-model="search" type="search" placeholder="Nama modul..." autocomplete="off"></label><label>Kelompok<select v-model="category"><option value="all">Semua kelompok</option><option v-for="g in groups" :key="g.id" :value="g.id">{{g.label}}</option></select></label><label>Prioritas<select v-model="priority"><option value="all">Semua modul</option><option value="overdue">Lewat tenggat</option><option value="upcoming">Jatuh tempo 30 hari</option><option value="references">Referensi proses</option><option value="deadlines">Memiliki tenggat</option><option value="critical">High / Critical / At risk</option><option value="pending">Pekerjaan tertunda</option><option value="incomplete">Data belum lengkap</option><option value="operational">Perhatian operasional</option><option value="unavailable">Belum tersedia</option></select></label><label>Grafik<select v-model="chartStyle"><option value="donut">Donat</option><option value="bar">Batang</option></select></label><button class="button button-quiet" @click="search='';category='all';priority='all'">Reset filter</button></div>
 <p class="monitor-scope-note muted">Filter berlaku pada seluruh ringkasan, grafik, prioritas, dan ekspor. Indikator dapat mencakup record yang sama; jumlah antarindikator tidak dijumlahkan sebagai total unik.</p>
 <div class="monitor-kpis"><button type="button" @click="priority='all'"><span>Modul terpantau</span><strong>{{totals.modules}}</strong><small>Modul dengan data tersedia</small></button><button type="button" class="monitor-kpi-danger" @click="priority='overdue'"><span>Lewat tenggat</span><strong>{{totals.overdue}}</strong><small>Renewal, review, dan tindak lanjut</small></button><button type="button" class="monitor-kpi-warning" @click="priority='upcoming'"><span>Jatuh tempo 30 hari</span><strong>{{totals.upcoming}}</strong><small>Termasuk tenggat hari ini</small></button><button type="button" @click="priority='unavailable'"><span>Modul belum tersedia</span><strong>{{totals.unavailable}}</strong><small>Periksa kembali saat muat ulang</small></button><button type="button" @click="priority='critical'"><span>High / Critical / At risk</span><strong>{{totals.critical}}</strong><small>Indikator sesuai penilaian tiap modul</small></button><button type="button" @click="priority='pending'"><span>Pekerjaan tertunda</span><strong>{{totals.pending}}</strong><small>Assessment, pengesahan, dan sasaran</small></button><button type="button" @click="priority='incomplete'"><span>Data belum lengkap</span><strong>{{totals.incomplete}}</strong><small>Penilaian, evidence, jadwal, atau konfigurasi</small></button><button type="button" @click="priority='references'"><span>Referensi proses</span><strong>{{totals.references}}</strong><small>Panduan framework dan tiering</small></button></div>
 <article class="monitor-panel monitor-coverage"><div class="monitor-panel-heading"><div><p class="eyebrow">CAKUPAN IT GOVERNANCE</p><h3>Monitoring per kelompok</h3></div><span class="monitor-tag">{{visibleModules.length}} modul dalam filter</span></div><div class="monitor-group-grid"><button v-for="g in groupSummary" :key="g.id" class="monitor-group-card" type="button" @click="category=g.id"><strong>{{g.label}}</strong><span>{{g.ready}} / {{g.total}} sumber tersedia</span><div class="monitor-bar-track"><span :style="{width:g.ready/g.total*100+'%',background:'#4b83da'}"></span></div><small>{{g.attention}} modul perlu perhatian &middot; {{g.unavailable}} belum tersedia</small></button></div></article>
 <div class="monitor-overview-grid"><article class="monitor-panel"><div class="monitor-panel-heading"><div><p class="eyebrow">AKTIVITAS DATA</p><h3>Tren record baru</h3></div><span class="monitor-tag">6 bulan</span></div><p class="muted">Jumlah record dibuat per bulan pada modul yang memiliki tanggal pembuatan. Bukan riwayat perubahan skor risiko.</p><svg v-if="trend.length" class="monitor-trend" viewBox="0 0 680 205" role="img" aria-label="Tren record baru selama enam bulan"><defs><linearGradient id="monitorTrendFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#4b83da" stop-opacity=".25"/><stop offset="100%" stop-color="#4b83da" stop-opacity=".02"/></linearGradient></defs><g v-for="tick in [0,.5,1]" :key="tick"><line x1="40" x2="640" :y1="160-tick*120" :y2="160-tick*120" stroke="#e7edf5"/><text x="30" :y="164-tick*120" text-anchor="end" class="monitor-svg-label">{{Math.round(maxTrend*tick)}}</text></g><path :d="trendLine+' L630,160 L50,160 Z'" fill="url(#monitorTrendFill)"/><path :d="trendLine" fill="none" stroke="#4b83da" stroke-width="3" stroke-linecap="round"/><g v-for="p in trendPoints" :key="p.label"><circle :cx="p.x" :cy="p.y" r="5" fill="#fff" stroke="#4b83da" stroke-width="3"><title>{{p.label}}: {{p.value}}</title></circle><text :x="p.x" :y="p.y-12" text-anchor="middle" class="monitor-svg-value">{{p.value}}</text><text :x="p.x" y="190" text-anchor="middle" class="monitor-svg-label" data-no-translate>{{p.label}}</text></g></svg><p v-else class="monitor-empty">Belum ada data tren yang dapat ditampilkan.</p></article>
 <article class="monitor-panel"><div class="monitor-panel-heading"><div><p class="eyebrow">PERLU PERHATIAN</p><h3>Prioritas tindak lanjut lintas modul</h3></div></div><p class="muted">Ringkasan per modul, mencakup tenggat, risiko tinggi, pekerjaan tertunda, dan kelengkapan data. Buka modul untuk menindaklanjuti.</p><div v-if="attention.length" class="monitor-attention"><button v-for="m in pagedAttention" :key="m.id" :disabled="m.state!=='ready'" @click="openModule(m)"><span>{{m.title}}<small class="monitor-attention-detail">{{m.state==='unavailable'?'Sumber belum tersedia':(m.issues?.critical||0)+' prioritas tinggi · '+(m.issues?.pending||0)+' tertunda · '+(m.issues?.incomplete||0)+' belum lengkap'+(m.issues?.operational?' / '+m.issues.operational+' event gagal':'')}}</small></span><span><b class="monitor-overdue">{{m.overdue||0}}</b> <span>lewat</span> <b class="monitor-upcoming">{{m.upcoming||0}}</b> <span>segera</span></span></button></div><p v-else class="monitor-empty">Tidak ada indikator yang perlu perhatian dalam filter ini.</p><nav v-if="attentionPages>1" class="monitor-priority-pagination" aria-label="Halaman prioritas monitoring"><button class="button button-quiet" type="button" :disabled="attentionPage===1" @click="attentionPage--">Sebelumnya</button><span aria-live="polite">{{attentionPage}} / {{attentionPages}}</span><button class="button button-quiet" type="button" :disabled="attentionPage===attentionPages" @click="attentionPage++">Berikutnya</button></nav></article></div>

 <p class="muted">{{visibleModules.length}} / {{modules.length}} <span>modul ditampilkan</span></p>
 <div class="monitor-module-grid"><article v-for="m in visibleModules" :key="m.id" class="monitor-panel monitor-module" :data-monitor-module="m.id"><div class="monitor-panel-heading"><h3>{{m.title}}</h3><span :class="['monitor-status',m.state==='ready'?'ready':'unavailable']">{{m.state==='ready'?'Tersedia':'Belum tersedia'}}</span></div><template v-if="m.state==='ready'"><div class="monitor-module-number"><strong>{{m.total===null?'\u2014':m.total}}</strong><span>{{m.unit}}</span></div><p v-if="m.reference" class="muted">Modul panduan; tidak memiliki register transaksi untuk grafik.</p><p v-if="m.note" class="muted">{{m.note}}</p><p v-if="m.ownOnly" class="muted">Hanya file yang Anda unggah.</p><div v-if="slices(m).length" class="monitor-chart"><svg v-if="chartStyle==='donut'" viewBox="0 0 130 130" class="monitor-donut" role="img" :aria-label="m.title+' - distribusi'"><circle cx="65" cy="65" r="48" fill="none" stroke="#eef2f7" stroke-width="15"/><circle v-for="slice in slices(m)" :key="slice.label" cx="65" cy="65" r="48" fill="none" :stroke="slice.color" stroke-width="15" pathLength="100" :stroke-dasharray="`${slice.percent} ${100-slice.percent}`" :stroke-dashoffset="-slice.offset" transform="rotate(-90 65 65)"><title>{{slice.label}}: {{slice.value}} ({{Math.round(slice.percent)}}%)</title></circle><text x="65" y="71" text-anchor="middle" class="monitor-ring-total">{{slices(m).reduce((n,s)=>n+s.value,0)}}</text></svg><div class="monitor-legend"><div v-for="slice in slices(m)" :key="slice.label" class="monitor-legend-item"><div><span class="monitor-color" :style="{background:slice.color}"></span><span>{{slice.label}}</span><strong>{{slice.value}}</strong></div><div v-if="chartStyle==='bar'" class="monitor-bar-track"><span :style="{width:slice.percent+'%',background:slice.color}"></span></div></div></div></div><p v-else-if="m.total===0" class="monitor-empty">Belum ada data.</p><div v-if="m.progress!==undefined" class="monitor-progress"><div><span>{{m.id==='server-racks'?'Pemakaian kapasitas':'Progres pencatatan'}}</span><strong>{{m.progress}}%</strong></div><progress :value="m.progress" max="100" :aria-label="m.title+' - progres'"></progress></div><div v-if="m.issues && Object.values(m.issues).some(n=>n>0)" class="monitor-issue-tags"><span v-if="m.issues.critical">{{m.issues.critical}} prioritas tinggi</span><span v-if="m.issues.pending">{{m.issues.pending}} tertunda</span><span v-if="m.issues.operational">{{m.issues.operational}} event gagal</span><span v-if="m.issues.incomplete">{{m.issues.incomplete}} belum lengkap</span></div><dl class="monitor-metrics"><div v-for="entry in m.metrics" :key="entry.label"><dt>{{entry.label}}</dt><dd>{{entry.value===null?'\u2014':entry.value}}</dd></div><div v-if="m.overdue!==undefined"><dt>Lewat tenggat</dt><dd class="monitor-overdue">{{m.overdue}}</dd></div><div v-if="m.upcoming!==undefined"><dt>Jatuh tempo 30 hari</dt><dd class="monitor-upcoming">{{m.upcoming}}</dd></div></dl><p v-if="m.lastBackup" class="muted"><span>Backup terakhir:</span> <span data-no-translate>{{new Date(m.lastBackup).toLocaleDateString('en-GB',{timeZone:'Asia/Bangkok'})}}</span></p><button class="button button-quiet monitor-open" @click="openModule(m)">Buka modul <svg aria-hidden="true" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M7 17 17 7M7 7h10v10"/></svg></button></template><p v-else class="monitor-empty">Data modul belum dapat dimuat. Modul lain tetap ditampilkan.</p></article></div>
 <p v-if="!visibleModules.length" class="insight-panel monitor-empty">Tidak ada modul yang cocok dengan filter atau hak akses Anda.</p><p class="muted monitor-footnote">Dashboard menampilkan ringkasan data aplikasi, bukan pemeriksaan kesehatan perangkat atau layanan secara langsung. Status SMTP menunjukkan konfigurasi tersimpan, bukan keberhasilan pengiriman email.</p>
 </template>
</section>
</template>

<style>
.monitoring-dashboard{color:var(--ink,#243f61)}
.monitoring-dashboard .monitor-hero{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:25px 28px;border-radius:16px;background:linear-gradient(120deg,#183b61,#245b83 65%,#257b79);color:#fff;box-shadow:0 8px 24px #244f7b14;margin-bottom:22px}
.monitoring-dashboard .monitor-hero strong{font-size:20px}.monitoring-dashboard .monitor-hero p{margin:8px 0;color:#e0ebf8}.monitoring-dashboard .monitor-hero small{color:#c4d8ee}.monitoring-dashboard .monitor-live-dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:#7bdec4;margin-right:10px;box-shadow:0 0 0 5px #7bdec422}.monitoring-dashboard .monitor-auto{display:flex;gap:8px;align-items:center;font-size:12px;flex-shrink:0}
.monitoring-dashboard .monitor-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:22px}.monitoring-dashboard .monitor-kpis > button{padding:20px;background:#fff;border:1px solid #dfE8f3;border-radius:14px;border-top:3px solid #4b83da;display:flex;flex-direction:column;gap:7px}.monitoring-dashboard .monitor-kpis strong{font-size:34px;line-height:1.2;font-variant-numeric:tabular-nums}.monitoring-dashboard .monitor-kpis span{font-size:13px;font-weight:600}.monitoring-dashboard .monitor-kpis small{font-size:11px;color:#6d829d}.monitoring-dashboard .monitor-kpis .monitor-kpi-danger{border-top-color:#e25964}.monitoring-dashboard .monitor-kpis .monitor-kpi-warning{border-top-color:#eeb550}
.monitoring-dashboard .monitor-overview-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:20px;margin-bottom:22px}.monitoring-dashboard .monitor-panel{background:#fff;border:1px solid #dfe8f3;border-radius:14px;padding:22px;min-width:0;box-shadow:0 3px 12px #365b8210}.monitoring-dashboard .monitor-panel-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.monitoring-dashboard .monitor-panel h3{font-size:16px;line-height:1.45;margin:0}.monitoring-dashboard .monitor-panel .muted{font-size:12px;line-height:1.7}.monitoring-dashboard .monitor-panel .eyebrow{font-size:10px;margin:0 0 8px}.monitoring-dashboard .monitor-tag{padding:5px 10px;background:#f0f5fc;border-radius:20px;font-size:11px;white-space:nowrap}
.monitoring-dashboard .monitor-trend{display:block;width:100%;height:auto;margin-top:12px}.monitoring-dashboard .monitor-svg-label{font-size:11px;fill:#7487a0}.monitoring-dashboard .monitor-svg-value{font-size:12px;fill:#244b7a;font-weight:600}.monitoring-dashboard .monitor-attention{max-height:260px;overflow:auto;margin-top:16px}.monitoring-dashboard .monitor-attention button{display:flex;justify-content:space-between;gap:16px;width:100%;padding:12px 0;border:0;border-bottom:1px solid #edf1f6;background:transparent;text-align:left;font:inherit;font-size:12px;color:inherit;cursor:pointer}.monitoring-dashboard .monitor-attention button:hover{background:#f6f9fd}.monitoring-dashboard .monitor-attention button>span:last-child{white-space:nowrap;font-size:11px}.monitoring-dashboard .monitor-overdue{color:#d94a59}.monitoring-dashboard .monitor-upcoming{color:#af770b}
.monitoring-dashboard .monitor-filters{display:flex;align-items:flex-end;flex-wrap:wrap;gap:12px;padding:16px;background:#fff;border:1px solid #dfe8f3;border-radius:12px}.monitoring-dashboard .monitor-filters label{display:flex;flex-direction:column;gap:7px;flex:1 1 140px;font-size:12px;min-width:0}.monitoring-dashboard .monitor-filters :is(input,select){width:100%;min-width:0;min-height:38px;padding:9px 10px;border:1px solid #d8e3f1;border-radius:8px;font:inherit;color:inherit;background:#fff;box-sizing:border-box}
